    fdp = atheris.FuzzedDataProvider(data)
    text = fdp.ConsumeUnicodeNoSurrogates(fdp.remaining_bytes())

    if not text:
        return

    # Fuzz arrow.get() with string input
    try:
        arrow.get(text)
    except (ParserError, ValueError, TypeError, OverflowError, AttributeError):
        pass

