# coverage. However, atheris still provides coverage-guided fuzzing through
# libFuzzer's instrumentation of the C code if compiled with sanitizers.
# We use instrument_imports() anyway for any Python wrapper code.

with atheris.instrument_imports():
    import ujson

def TestOneInput(data):
